mapper.select:
SELECT a.*, u.real_name AS handler_name
FROM alarm_record a
LEFT JOIN `user` u ON a.handler_id = u.id

    AND a.status = #{status}
    AND a.level = #{level}

ORDER BY a.create_time DESC

mapper.update:
UPDATE alarm_record
status = #{status}, handler_id = #{handlerId}, handle_time = #{handleTime}, handle_remark = #{handleRemark},
WHERE id = #{id}
